DROP TABLE IF EXISTS club_rating_state;
CREATE TABLE club_rating_state (
    user_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
    mu DOUBLE NOT NULL,
    rd DOUBLE NOT NULL,
    games_played INT NOT NULL,
    first_event BIGINT NOT NULL,
    last_event BIGINT NOT NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
-- Per-event ledger: records each player's rating snapshot immediately before
-- and after an event was applied. Lets "Update Club Ratings" detect a
-- re-publish (corrected scores) and roll back to the pre-event snapshot
-- before reapplying, instead of double-counting the event.
DROP TABLE IF EXISTS club_rating_event_log;
CREATE TABLE club_rating_event_log (
    event_id BIGINT UNSIGNED NOT NULL,
    user_id BIGINT UNSIGNED NOT NULL,
    mu_before DOUBLE NOT NULL,
    rd_before DOUBLE NOT NULL,
    games_before INT NOT NULL,
    last_event_before BIGINT NOT NULL,
    mu_after DOUBLE NOT NULL,
    rd_after DOUBLE NOT NULL,
    games_after INT NOT NULL,
    processed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (event_id, user_id)
) ENGINE=InnoDB;
-- Left empty at bootstrap time — it's forward-looking only, populated as
-- "Update Club Ratings" runs against real future events.
